const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const KEY='carebridge-v2-demo';
const initial=()=>({role:'patient',queue:{prefix:'CAR',patient:25,serving:20,last:31,avg:5,paused:false,log:[]},records:[{id:1,title:'Complete blood count',hospital:'Sanjeevani Medical Centre',date:'2026-10-08',type:'Lab report'},{id:2,title:'Cardiology prescription',hospital:'Sanjeevani Medical Centre',date:'2026-09-28',type:'Prescription'}],permissions:{checkins:true,meds:true,records:false},requests:[],meds:[{id:1,name:'Atorvastatin',instruction:'1 tablet',time:'20:00',note:'After dinner',status:'unconfirmed'}],doseHistory:[],moods:[3,4,3,5,4,4],journals:[],checkin:null});
let state;try{state=JSON.parse(localStorage.getItem(KEY))||initial()}catch{state=initial()}
const save=()=>localStorage.setItem(KEY,JSON.stringify(state));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const icon=id=>`<svg aria-hidden="true"><use href="#i-${id}"/></svg>`;
const nowTime=()=>new Intl.DateTimeFormat('en-IN',{hour:'2-digit',minute:'2-digit'}).format(new Date());
let toastTimer;function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2600)}
const titles={dashboard:['Tuesday, 13 October','Good evening, Ananya'],queue:['LIVE HOSPITAL STATUS','QueueCare'],map:['INDOOR WAYFINDING','CareClue'],records:['YOUR DOCUMENTS','HealthStory'],circle:['YOUR TRUSTED CIRCLE','CareCircle'],meds:['TODAY’S SCHEDULE','MedMinder'],mind:['PRIVATE WELL-BEING','MindMate'],ussd:['ACCESSIBILITY LAYER','Low-data access']};
function go(page){$$('.page').forEach(x=>x.classList.toggle('active',x.id===`page-${page}`));$$('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===page));$('#pageEyebrow').textContent=titles[page][0];$('#pageTitle').textContent=titles[page][1];$('#sidebar').classList.remove('open');$('#menuBtn').setAttribute('aria-expanded','false');window.scrollTo(0,0);$('#main').focus();if(page==='ussd')renderUssd();if(page==='map')renderMap();}
$$('[data-page]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.page)));$$('[data-go]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.go)));
$('#menuBtn').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('#menuBtn').setAttribute('aria-expanded',open)});
function token(n,p=state.queue.prefix){return `${p}-${String(n).padStart(3,'0')}`}
function queueMetrics(){const ahead=Math.max(0,state.queue.patient-state.queue.serving-1),base=ahead*state.queue.avg;return{ahead,wait:ahead?`${Math.max(1,base-2)}–${base+8} min`:'You’re next'}}
function renderQueue(){const q=state.queue,m=queueMetrics();['#dashToken','#patientToken'].forEach(s=>$(s).textContent=token(q.patient));['#dashServing','#nowServing'].forEach(s=>$(s).textContent=token(q.serving));['#dashWait','#waitEstimate'].forEach(s=>$(s).textContent=m.wait);$('#aheadCount').textContent=m.ahead;$('#progressFill').style.width=`${Math.min(100,Math.max(7,(q.serving/q.patient)*100))}%`;$('#queueState').textContent=q.paused?'Queue paused':'Queue active';$('#queueState').className=`badge ${q.paused?'':'success'}`;$('#togglePause').textContent=q.paused?'Resume queue':'Pause queue';$('#queueLog').innerHTML=q.log.length?q.log.slice(0,6).map(x=>`<div class="log-row"><span>${esc(x.text)}</span><small>${esc(x.time)}</small></div>`).join(''):'<p class="muted">No staff updates yet.</p>';renderTimeline()}
$('#tokenForm').addEventListener('submit',e=>{e.preventDefault();const p=$('#tokenDept').value;if(state.queue.prefix===p&&state.queue.patient>state.queue.serving){$('#tokenMessage').textContent=`Active token ${token(state.queue.patient)} already exists.`;return}state.queue.prefix=p;state.queue.patient=++state.queue.last;state.queue.serving=Math.max(1,state.queue.last-5);state.queue.paused=false;save();renderQueue();$('#tokenMessage').textContent=`Token ${token(state.queue.patient)} generated successfully.`;toast('Digital token created')});
function staffAction(type){if(type!=='pause'&&state.queue.paused)return toast('Resume the queue first');if(type==='next'){state.queue.serving++;state.queue.log.unshift({text:`Called ${token(state.queue.serving)}`,time:nowTime()})}if(type==='complete'){state.queue.avg=Math.max(3,Math.min(12,state.queue.avg+(Math.random()>.5?1:-1)));state.queue.serving++;state.queue.log.unshift({text:`Completed consultation; now ${token(state.queue.serving)}`,time:nowTime()})}if(type==='pause'){state.queue.paused=!state.queue.paused;state.queue.log.unshift({text:state.queue.paused?'Queue paused by staff':'Queue resumed by staff',time:nowTime()})}save();renderQueue();toast('Queue status updated')}
$('#callNext').onclick=()=>staffAction('next');$('#completeConsult').onclick=()=>staffAction('complete');$('#togglePause').onclick=()=>staffAction('pause');setInterval(()=>{$('#queueClock').textContent=nowTime()},1000);

const nodes={Entrance:{x:70,y:340,type:'entry'},Reception:{x:190,y:340},Lift:{x:315,y:340,type:'lift'},Stairs:{x:315,y:245,type:'stairs'},Cardiology:{x:535,y:110},Pharmacy:{x:530,y:340},Laboratory:{x:535,y:235},Emergency:{x:145,y:105},Restrooms:{x:315,y:110}};
const edges=[['Entrance','Reception',1,true],['Reception','Lift',1,true],['Reception','Stairs',1,false],['Lift','Pharmacy',2,true],['Lift','Laboratory',2,true],['Lift','Restrooms',2,true],['Stairs','Laboratory',1,false],['Stairs','Cardiology',2,false],['Laboratory','Cardiology',1,true],['Restrooms','Cardiology',2,true],['Reception','Emergency',2,true],['Emergency','Restrooms',2,true]];
Object.keys(nodes).forEach(n=>{$('#routeStart').add(new Option(n,n));$('#routeEnd').add(new Option(n,n))});$('#routeStart').value='Entrance';$('#routeEnd').value='Cardiology';let activeRoute=[];
function shortest(start,end,accessible){const dist={},prev={},unseen=new Set(Object.keys(nodes));Object.keys(nodes).forEach(n=>dist[n]=Infinity);dist[start]=0;while(unseen.size){let u=[...unseen].sort((a,b)=>dist[a]-dist[b])[0];unseen.delete(u);if(u===end)break;for(const [a,b,w,ok] of edges){if(accessible&&!ok)continue;const v=a===u?b:b===u?a:null;if(!v||!unseen.has(v))continue;const alt=dist[u]+w;if(alt<dist[v]){dist[v]=alt;prev[v]=u}}}const path=[];for(let u=end;u;u=prev[u]){path.unshift(u);if(u===start)break}return path[0]===start?path:[]}
function renderMap(){const svg=$('#hospitalMap');let h='<rect x="20" y="20" width="680" height="380" rx="18" fill="#f8faf7" stroke="#b8c8c1" stroke-width="2"/>';for(const [a,b] of edges){const n1=nodes[a],n2=nodes[b],on=activeRoute.some((n,i)=>n===a&&activeRoute[i+1]===b||n===b&&activeRoute[i+1]===a);h+=`<line class="${on?'route-edge':'edge'}" x1="${n1.x}" y1="${n1.y}" x2="${n2.x}" y2="${n2.y}"/>`}for(const [name,n] of Object.entries(nodes)){const on=activeRoute.includes(name);h+=`<circle class="${on?'route-node':'node'}" cx="${n.x}" cy="${n.y}" r="11"/><text class="room-label" x="${n.x}" y="${n.y-18}" text-anchor="middle">${name}</text>`}svg.innerHTML=h}
$('#routeForm').addEventListener('submit',e=>{e.preventDefault();activeRoute=shortest($('#routeStart').value,$('#routeEnd').value,$('#accessibleRoute').checked);const mins=Math.max(2,(activeRoute.length-1)*2);$('#routeResult').innerHTML=activeRoute.length?`<span class="badge success">${mins} min · ${activeRoute.length-1} steps</span><ol class="directions">${activeRoute.map((n,i)=>`<li><b>${i+1}</b><span>${i?'Continue to':'Start at'} <strong>${n}</strong></span></li>`).join('')}</ol>`:'<p class="error">No supported route was found.</p>';renderMap();toast('Route calculated')});

const recordDialog=$('#recordDialog');$('#openRecordForm').onclick=()=>recordDialog.showModal();
function renderRecords(){const q=$('#recordSearch').value.toLowerCase(),type=$('#recordFilter').value;const items=state.records.filter(r=>(type==='all'||r.type===type)&&`${r.title} ${r.hospital} ${r.type}`.toLowerCase().includes(q));$('#recordsList').innerHTML=items.length?items.sort((a,b)=>b.date.localeCompare(a.date)).map(r=>`<article class="record-card"><div class="record-type">${icon('file')}</div><div><h3>${esc(r.title)}</h3><p>${esc(r.hospital)} · ${esc(r.type)} · ${new Date(r.date+'T00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})}</p></div><div class="record-actions">${r.data?`<a href="${r.data}" download="${esc(r.fileName||r.title)}" aria-label="Download ${esc(r.title)}">↓</a>`:''}<button data-delete-record="${r.id}" aria-label="Delete ${esc(r.title)}">${icon('trash')}</button></div></article>`).join(''):'<div class="empty-state">No records match these filters.</div>';$$('[data-delete-record]').forEach(b=>b.onclick=()=>{state.records=state.records.filter(r=>r.id!=b.dataset.deleteRecord);save();renderRecords();renderTimeline();toast('Record deleted')})}
$('#recordSearch').oninput=renderRecords;$('#recordFilter').onchange=renderRecords;
$('#recordForm').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget),file=f.get('file');$('#recordError').textContent='';if(file?.size>1.5*1024*1024){$('#recordError').textContent='This file is larger than 1.5 MB. Choose a smaller demo file.';return}let data=null;if(file?.size)data=await new Promise((res,rej)=>{const rd=new FileReader;rd.onload=()=>res(rd.result);rd.onerror=rej;rd.readAsDataURL(file)});state.records.push({id:Date.now(),title:f.get('title'),hospital:f.get('hospital'),date:f.get('date'),type:f.get('type'),data,fileName:file?.name});save();e.currentTarget.reset();recordDialog.close();renderRecords();renderTimeline();toast('Health record saved locally')});

function sendCheckin(text){const req={id:Date.now(),text,time:new Date().toISOString(),status:'Waiting'};state.checkin=req;state.requests.unshift(req);save();renderCare();renderTimeline();toast(`${text} check-in sent`)}$$('[data-checkin]').forEach(b=>b.onclick=()=>sendCheckin(b.dataset.checkin));
function renderCare(){const c=state.checkin;$('#lastCheckin').textContent=c?`Last sent ${new Date(c.time).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})}: ${c.text}`:'No check-in sent today';$('#careRequests').innerHTML=state.requests.length?state.requests.slice(0,7).map(r=>`<div class="request-item"><p><b>${esc(r.text)}</b></p><small>${new Date(r.time).toLocaleString('en-IN')} · ${r.status}</small>${state.role==='caregiver'&&r.status!=='Acknowledged'?`<button data-ack="${r.id}">Acknowledge</button>`:''}</div>`).join(''):'<div class="empty-state">No requests yet.</div>';$$('[data-ack]').forEach(b=>b.onclick=()=>{const r=state.requests.find(x=>x.id==b.dataset.ack);r.status='Acknowledged';save();renderCare();toast('Request acknowledged')});$('#circleAccess').textContent=state.permissions.checkins?'Caregiver access on':'Caregiver access limited';$$('.permission').forEach(x=>x.checked=!!state.permissions[x.dataset.permission])}
$$('.permission').forEach(x=>x.onchange=()=>{state.permissions[x.dataset.permission]=x.checked;save();renderCare();toast('Sharing preference updated')});let cameraStream=null;$('#cameraToggle').onclick=async()=>{if(cameraStream){cameraStream.getTracks().forEach(t=>t.stop());cameraStream=null;$('#cameraVideo').style.display='none';$('#cameraPlaceholder').style.display='grid';$('#cameraToggle').textContent='Start camera';return}try{cameraStream=await navigator.mediaDevices.getUserMedia({video:true,audio:false});$('#cameraVideo').srcObject=cameraStream;$('#cameraVideo').style.display='block';$('#cameraPlaceholder').style.display='none';$('#cameraToggle').textContent='Stop camera';toast('Camera started — you remain in control')}catch{$('#cameraPlaceholder span').textContent='Camera permission was not granted';toast('Unable to start camera')}};

const medDialog=$('#medDialog');$('#openMedForm').onclick=()=>medDialog.showModal();$('#medForm').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget);state.meds.push({id:Date.now(),name:f.get('name'),instruction:f.get('instruction'),time:f.get('time'),note:f.get('note'),status:'unconfirmed'});save();e.currentTarget.reset();medDialog.close();renderMeds();toast('Medication schedule added')});
function setDose(id,status){const m=state.meds.find(x=>x.id==id);m.status=status;state.doseHistory.unshift({id:Date.now(),name:m.name,status,time:new Date().toISOString()});save();renderMeds();toast(`Dose marked ${status}`)}
function renderMeds(){const ms=[...state.meds].sort((a,b)=>a.time.localeCompare(b.time));$('#medList').innerHTML=ms.length?ms.map(m=>`<article class="med-item"><div class="med-time">${new Date('2020-01-01T'+m.time).toLocaleTimeString('en-IN',{hour:'numeric',minute:'2-digit'})}</div><div><h3>${esc(m.name)}</h3><p>${esc(m.instruction)}${m.note?' · '+esc(m.note):''}</p></div><div class="dose-actions"><button class="${m.status==='taken'?'active':''}" data-dose="${m.id}:taken">Taken</button><button class="${m.status==='skipped'?'active':''}" data-dose="${m.id}:skipped">Skipped</button></div></article>`).join(''):'<div class="empty-state">No medication schedules yet.</div>';$$('[data-dose]').forEach(b=>b.onclick=()=>{const [id,s]=b.dataset.dose.split(':');setDose(id,s)});$('#medHistory').innerHTML=state.doseHistory.length?state.doseHistory.slice(0,8).map(h=>`<div class="history-row"><b>${esc(h.name)}</b><span class="badge ${h.status==='taken'?'success':''}">${esc(h.status)}</span><small>${new Date(h.time).toLocaleString('en-IN')}</small></div>`).join(''):'<div class="empty-state">Status updates will appear here.</div>';const due=state.meds.filter(m=>m.status==='unconfirmed').length;$('#dashMed').textContent=`${due} dose${due===1?'':'s'} due`}

function renderMind(){const days=['Wed','Thu','Fri','Sat','Sun','Mon','Today'];const vals=[...state.moods].slice(-7);while(vals.length<7)vals.unshift(0);$('#moodChart').innerHTML=vals.map((v,i)=>`<div class="chart-col"><div class="chart-bar" style="height:${v?v*18:5}%" title="${v||'No entry'} out of 5"></div><span>${days[i]}</span></div>`).join('');$('#journalList').innerHTML=state.journals.length?state.journals.slice(0,5).map(j=>`<article class="journal-entry"><small>${new Date(j.time).toLocaleString('en-IN')}</small><p>${esc(j.text)}</p><button data-delete-journal="${j.id}" aria-label="Delete journal entry">${icon('trash')}</button></article>`).join(''):'';$$('[data-delete-journal]').forEach(b=>b.onclick=()=>{state.journals=state.journals.filter(j=>j.id!=b.dataset.deleteJournal);save();renderMind();toast('Journal entry deleted')})}
$$('[data-mood]').forEach(b=>b.onclick=()=>{const v=+b.dataset.mood;state.moods.push(v);state.moods=state.moods.slice(-7);save();$$('[data-mood]').forEach(x=>x.classList.toggle('selected',x===b));$('#moodMessage').textContent='Mood saved privately on this device.';renderMind();toast('Mood check-in saved')});$('#journalForm').onsubmit=e=>{e.preventDefault();state.journals.unshift({id:Date.now(),text:$('#journalText').value,time:new Date().toISOString()});save();e.currentTarget.reset();renderMind();toast('Private reflection saved')};const prompts=['What felt manageable today?','What gave you a moment of calm?','What would you like to make room for tomorrow?','Who or what supported you today?'];$('#newPrompt').onclick=()=>$('#reflectionPrompt').textContent=prompts[Math.floor(Math.random()*prompts.length)];

let ussdStep='menu';function renderUssd(msg){const q=state.queue,m=queueMetrics();const menu='Welcome to CareBridge\n\n1. Check Token Status\n2. Find Hospital Department\n3. Check Appointment\n4. Hospital Help Desk\n0. Exit\n\nReply with an option:';$('#ussdScreen').textContent=msg||menu;$('#ussdInput').value=''}function ussdSend(){const v=$('#ussdInput').value.trim(),m=queueMetrics();let text;if(v==='1')text=`QUEUE STATUS\nToken: ${token(state.queue.patient)}\nNow serving: ${token(state.queue.serving)}\nPatients ahead: ${m.ahead}\nEstimated wait: ${m.wait}\n\n0. Back`;else if(v==='2')text='DEPARTMENT FINDER\nCardiology: Floor 2, Room 204\nFrom entrance: Reception > Lift > Cardiology\n\n0. Back';else if(v==='3')text='UPCOMING APPOINTMENT\nCardiology consultation\nToday · Queue token active\nDr. Meera Shah\n\n0. Back';else if(v==='4')text='HELP DESK\nSanjeevani Medical Centre\nDemo line: 1800-000-CARE\nEmergency: contact local emergency services\n\n0. Back';else if(v==='0')text=null;else text='Invalid option. Please enter 1, 2, 3, 4 or 0.';renderUssd(text)}$('#ussdSend').onclick=ussdSend;$('#ussdInput').onkeydown=e=>{if(e.key==='Enter')ussdSend()};$('#ussdRestart').onclick=()=>renderUssd();$('#lowBandwidth').onclick=()=>{document.body.classList.add('text-only');toast('Text-only view enabled')};

function renderTimeline(){const rows=[{icon:'Q',title:`Queue token ${token(state.queue.patient)} active`,meta:`Now serving ${token(state.queue.serving)} · ${queueMetrics().wait}`},...state.records.slice(-2).reverse().map(r=>({icon:'R',title:r.title,meta:`${r.hospital} · ${r.date}`})),...(state.checkin?[{icon:'C',title:state.checkin.text,meta:`CareCircle · ${new Date(state.checkin.time).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})}`}]:[])];$('#dashboardTimeline').innerHTML=rows.slice(0,4).map(r=>`<div class="timeline-item"><span class="dot-icon">${r.icon}</span><p><b>${esc(r.title)}</b><small>${esc(r.meta)}</small></p><span>→</span></div>`).join('')}
$('#notifyBtn').onclick=async()=>{if(!('Notification'in window))return toast('Notifications are not supported here');if(Notification.permission==='granted')return toast('Medication notifications are enabled');const p=await Notification.requestPermission();toast(p==='granted'?'Notifications enabled':'Notification permission not granted')};
$('#roleSelect').value=state.role;function setRole(role){state.role=role;document.body.dataset.role=role;save();renderCare();toast(`Switched to ${role} view`)}$('#roleSelect').onchange=e=>setRole(e.target.value);document.body.dataset.role=state.role;
$('#resetDemo').onclick=()=>{if(confirm('Reset all CareBridge demo data on this browser?')){state=initial();save();location.reload()}};
renderQueue();renderRecords();renderCare();renderMeds();renderMind();renderMap();renderUssd();renderTimeline();
